#pragma once
#include <filesystem>
#include <functional>
#include <map>
#include <set>
#include <sstream>
#include <string>
#include <vector>
#include "ast/ast.hpp"
#include "error.hpp"

// Compiling requires several steps
// 1. Lexing to known tokens (lexer.hpp)
// 2. Parsing the lexical tokens into an Abstract Syntax Tree (AST) (parser.hpp)
//    - This is where we convert everything to logical steps, like math and function calls.
// 3. Compiling from the AST to LLVM IR (this file)
// 4. Handing the LLVM IR, together with the runtime library, to clang to produce the final executable (driver.hpp)
//
// The code generator emits textual LLVM IR, which means that it has no build-time dependency on LLVM itself. LLVM is
// only needed when producing the executable, where the user can pass any flags they want to it.

namespace blitz {
	class compiler {
		struct value {
			std::string        repr; // Operand without type, such as `%t1`, `42` or `@.str.0`.
			blitz::types::type type = blitz::types::type::UNKNOWN; // UNKNOWN means "no value" (void).
			std::string        sname;                              // Lower case name of the Type if this is an object. Empty for Null.
		};

		struct variable {
			std::string        pointer; // Operand for the storage location.
			blitz::types::type type;
			bool               constant;
			std::string        sname;     // Lower case name of the Type for objects.
			uint32_t           count = 0; // For fixed arrays: how many elements there are.
			uint32_t           dims  = 0; // For Dim arrays: how many dimensions there are. The pointer is the descriptor.
		};

		struct field_info {
			std::string        name;
			blitz::types::type type;
			std::string        sname;
			uint32_t           count; // 0 if this is not an array.
			uint32_t           index; // Index of the member in the LLVM structure.
		};

		struct type_info {
			std::string             name;
			std::string             llvm;  // Name of the LLVM structure.
			std::string             list;  // Global that holds the first and last object.
			std::vector<field_info> fields;
		};

		// Where something lives in memory.
		struct address {
			std::string        pointer;
			blitz::types::type type  = blitz::types::type::UNKNOWN;
			std::string        sname;
			uint32_t           count = 0; // Not 0 if this is an array and not an element.
			bool               constant = false;
		};

		struct function_info {
			std::string            symbol;
			ast::function const*   declaration;
		};

		// Module state
		std::ostringstream                   _constants;
		std::ostringstream                   _globals;
		std::ostringstream                   _declarations;
		std::ostringstream                   _definitions;
		std::set<std::string>                _declared;
		std::map<std::string, std::string>   _strings;
		std::map<std::string, variable>      _global_variables;
		std::map<std::string, variable>      _arrays; // Dim arrays, which have their own names.
		std::map<std::string, function_info> _functions;
		std::map<std::string, type_info>     _types;
		std::map<std::string, int64_t>       _const_values;
		std::string                          _return_sname;
		std::map<std::string, std::pair<std::string, ast::location>> _unknown; // Functions that were called but don't exist, so all can be reported at once.

		// Data, in the order it appears in the program.
		std::vector<std::string>             _data_items;  // LLVM constants, `{ i32, i64 }`.
		std::map<std::string, size_t>        _data_labels; // Index of the first item after a label, keyed by scope and label.
		std::string                          _scope;       // Which function is being generated, empty for the main program.
		size_t                               _counter;
		size_t                               _warnings;

		// Function state
		std::ostringstream              _body;
		std::ostringstream              _allocas;
		std::map<std::string, variable> _locals;
		std::vector<std::string>        _exits;
		blitz::types::type              _return_type;
		bool                            _in_main;
		bool                            _terminated;

		// Goto and Gosub, for the function that is being generated.
		std::set<std::string>                                 _labels;
		std::map<ast::gosub_statement const*, int>            _gosubs;
		std::string                                           _gosub_stack; // Pointer to the return addresses, empty if there are no Gosubs.
		std::string                                           _gosub_depth; // Pointer to how many there are.

		public:
		compiler();
		~compiler();

		/** Generate LLVM IR for the given program. Throws blitz::error on failure. */
		std::string generate(ast::program const& program);

		/** Number of warnings that were emitted while generating. */
		size_t warnings() const;

		private:
		// Errors and warnings
		blitz::error err(ast::location const& where, std::string const& reason) const;
		void         warn(ast::location const& where, std::string const& reason);

		// Emission
		std::string tmp();
		std::string label(const char* prefix);
		void        emit(std::string const& line);
		void        emit_terminator(std::string const& line);
		void        begin_label(std::string const& name);
		void        declare(std::string const& symbol, std::string const& line);
		std::string string_constant(std::string const& text);

		// Types and values
		value       zero(blitz::types::type type);
		value       constant(blitz::types::type type, double number);
		value       convert(value from, blitz::types::type to, ast::location const& where, bool warn, std::string const& to_sname = std::string());
		value       call_runtime(const char* symbol, blitz::types::type ret, std::vector<value> const& args);
		blitz::types::type common_type(blitz::types::type lhs, blitz::types::type rhs, ast::location const& where);
		std::string truthy(value v, ast::location const& where);
		value       from_bool(std::string const& i1);

		// Variables
		variable&   lookup(std::string const& name, blitz::types::type hint, std::string const& sname = std::string());
		variable*   find(std::string const& name);
		variable    create_local(std::string const& name, blitz::types::type type, bool constant, ast::location const& where, std::string const& sname = std::string(), uint32_t count = 0);
		variable*   find_dim(std::string const& name);
		address     gen_dim_address(ast::call const* node);
		uint32_t    array_count(ast::expression const* size, ast::location const& where);
		void        gen_dim(ast::dim_statement const* node);
		bool        fold_int(ast::expression const* expr, int64_t& out);
		type_info&  need_type(std::string const& name, ast::location const& where);
		void        register_types(ast::program const& program);
		address     gen_address(ast::expression const* expr);
		value       load_address(address const& addr);
		void        collect_globals(ast::block const& block);
		blitz::types::type static_type(ast::expression const* expr);

		// Expressions
		value gen(ast::expression const* expr);
		value gen_literal(ast::literal const* node);
		value gen_reference(ast::reference const* node);
		value gen_call(ast::call const* node);
		value gen_builtin(ast::call const* node, bool& handled);
		value gen_unary(ast::unary const* node);
		value gen_binary(ast::binary const* node);
		value gen_field(ast::field_access const* node);
		value gen_index(ast::index_access const* node);
		value gen_new(ast::new_object const* node);
		value gen_list_end(ast::list_end const* node);
		value gen_neighbor(ast::list_neighbor const* node);
		value gen_from_handle(ast::object_from_handle const* node);
		std::string compare(ast::binary::op kind, value lhs, value rhs, ast::location const& where);

		// Statements
		void gen_block(ast::block const& block);
		void gen_statement(ast::statement const* node);
		void gen_declare(ast::declare const* node);
		void gen_assign(ast::assign const* node);
		void gen_if(ast::if_statement const* node);
		void gen_while(ast::while_statement const* node);
		void gen_repeat(ast::repeat_statement const* node);
		void gen_for(ast::for_statement const* node);
		void gen_for_each(ast::for_statement const* node);
		void gen_delete(ast::delete_statement const* node);
		void gen_insert(ast::insert_statement const* node);
		void gen_select(ast::select_statement const* node);
		void gen_return(ast::return_statement const* node);
		void gen_function(ast::function const& fn);
		void gen_main(ast::program const& program);
		void begin_function();
		void collect_data(std::string const& scope, ast::block const& block);
		void gen_read(ast::read_statement const* node);
		void gen_restore(ast::restore_statement const* node);
		void prepare_flow(ast::block const& block);
		void gen_label(ast::label_statement const* node);
		void gen_goto(ast::goto_statement const* node);
		void gen_gosub(ast::gosub_statement const* node);
		void gen_gosub_return(ast::location const& where);
	};
} // namespace blitz
